function stripHTML(oldString) {

   var newString = "";
   var inTag = false;
   for(var i = 0; i < oldString.length; i++) {
        if(oldString.charAt(i) == '<') inTag = true;
        if(oldString.charAt(i) == '>') {
              if(oldString.charAt(i+1)!="<")
	{
		inTag = false;
		i++;
	}
        }
        if(!inTag) newString += oldString.charAt(i);
   }
   return newString;
}

function addCommas(nStr)
{
	nStr += '';
	x = nStr.split('.');
	x1 = x[0];
	x2 = x.length > 1 ? '.' + x[1] : '';
	var rgx = /(\d+)(\d{3})/;
	while (rgx.test(x1)) {
		x1 = x1.replace(rgx, '$1' + ',' + '$2');
	}
	return x1 + x2;
}

    function strip_tags (input, allowed) {
        allowed = (((allowed || "") + "").toLowerCase().match(/<[a-z][a-z0-9]*>/g) || []).join(''); // making sure the allowed arg is a string containing only tags in lowercase (<a><b><c>)
        var tags = /<\/?([a-z][a-z0-9]*)\b[^>]*>/gi,
            commentsAndPhpTags = /<!--[\s\S]*?-->|<\?(?:php)?[\s\S]*?\?>/gi;
        return input.replace(commentsAndPhpTags, '').replace(tags, function ($0, $1) {
            return allowed.indexOf('<' + $1.toLowerCase() + '>') > -1 ? $0 : '';
        });
    }



	function updateDB(screenarray, startnum)
	{
	//alert(screenarray.length);

	  if(top.advavail=="public") 
	  {
      //alert("You cannot edit this adventure until it is made unavailable to the public.");
      return false;
      }
      if (!startnum) startnum = 0;
    //else alert(top.advavail);

		//document.getElementById("loadingoverlay").style.display="block";
		//document.getElementById("loadingoverlaytext").style.display="block";
		//document.getElementById("throbgroup").style.display="block";
		document.getElementById("savingtext").style.visibility="visible";
		if(screenarray)
		{
		if(cyoXML.readyState==4 || cyoXML.readyState==0)
		{
		 var post="";
		 var orsc = 0;
		 var screencount = 0;
		  for (var x in screenarray)
		  {
		    if (screencount < startnum)
		    {
		      screencount++;
		      continue;
		    }
		    if (screencount >= (startnum + 50))
		    {
                cyoXML.onreadystatechange=function()
                {
                   updateDB(screenarray, startnum+50);
                };
                orsc = 1;
                break;
		    }

		    for (var y in screenarray[x])
            {
               if(y.substr(0,6)=="choice" || y=="id" || y=="xpos" || y=="ypos" || y=="deleted" || y=="name" )
               {
                  post+=x+"_"+y+"="+encodeURIComponent(screenarray[x][y])+"&";

               }
            }
            screencount++;
          }
      if(!post) return false; // nothin to do
      post+="origtop="+origtop;
      post+="&advid="+top.advid;
      //     top.document.getElementById("blehblah").innerHTML=post;
      //alert(startnum);
      //alert(post);
      //return false;
			cyoXML.open("POST","updateadv.php",true);
			cyoXML.setRequestHeader("Content-type","application/x-www-form-urlencoded");
			cyoXML.setRequestHeader("Content-length",post.length);
			if(!orsc) cyoXML.onreadystatechange=advResponse;
			//alert("send with orsc "+orsc+" and startnum "+startnum);
			cyoXML.send(post);
			return true;
		}
		else 
		{
			//setTimeout('updateDB('+top.advid+')',500);
		}
		}
		else return false;
		return true;
	}

	function sendAdventureRequest(id)
	{
		  /*document.getElementById("loadingoverlay").style.display="block";
		  document.getElementById("loadingoverlaytext").style.display="block";
		  document.getElementById("throbgroup").style.display="block";*/

		if(id>0)
		{
		if(cyoXML.readyState==4 || cyoXML.readyState==0)
		{
			cyoXML.open("GET","updateadv.php?id="+id,true);
			cyoXML.onreadystatechange=advResponse;
			cyoXML.send(null);
			var curfirst=document.getElementById("firstGroup"); 
      for(var i=(curfirst.childNodes.length-1);i>=0;i--)
        {
          curfirst.removeChild(curfirst.childNodes[i]);
        }
		}
		else 
		{
			setTimeout('sendAdventureRequest('+id+')',1000);
		}
		}
		else return false;
	}
