       else document.getElementById("avail").setAttribute("fill","#ccccff");
			var screens= xmlDocEl.getElementsByTagName("screen");
			if (browser!="Microsoft Internet Explorer") var index=1;
            else var index=0;
			for(var i=0;i<screens.length;i++)
			{

                var nodes=screens[i].childNodes;

                var currid=nodes[index].firstChild.data;
                allscreens[currid]=new Array();
