                {
                    if(nodes[j].nodeName=="#text")
                    {}
                    else
                    {
                        if(nodes[j].firstChild)
                        {
                            var thetext=nodes[j].firstChild.data.replace(/^\s\s*/, '').replace(/\s\s*$/, '').replace(/<br \/><br \/><br \/>/gm, "<br /><br />").replace(/(\r\n|\n|\r)/gm,"<br />");
                            eval ("allscreens["+currid+"]['"+nodes[j].nodeName+"']= '"+thetext+"';");
                        }
                        else eval ("allscreens["+currid+"]['"+nodes[j].nodeName+"']= ''");
