	var totalcount = 0;
      function buildScreen(sid, fromid, yoffset, marker)
      {

      var targetscreen;
       var screeninfo=allscreens[sid[1]];
       if(!screeninfo)
       {
       return false;
       }

       if(parseInt(sid[1])>parseInt(origtop)) origtop=parseInt(sid[1]);
       if(screeninfo['xpos']>0) var xoff=screeninfo['xpos'];
       else var xoff=50;
       if(screeninfo['ypos']>0) var yoff=screeninfo['ypos'];
       else var yoff=65+yoffset;

        var screenfull = screeninfo['wordcount'];
      if(fromid===false) makeRect(xoff,yoff,45,150,5,5,sid[1],screeninfo['name'],marker, screenfull);
      else if(connx[fromid])
       {
        if(!inArray(sid[1],connx[fromid])) makeChild(fromid,sid[1]);
        else return false;
       }
      else if(!connx[fromid]) makeChild(fromid,sid[1]);
      else return false;
      for (var num=1;num<=8;num++)
      {
        if(screeninfo['choice'+num]!="")
        {
          targetscreen=screeninfo['choice'+num].split("|Q-D-|");
          buildScreen(targetscreen,sid[1], yoffset,null);
        }
      }                         
      }                           

