      function doload() 
      {
        // SVG on the page should only be manipulated after the page is 
        // finished loading

 document.getElementById("SVGguy").addEventListener('mousedown', dragHandler, false);

      }

      function checkOffScreen()
{
   overdiv=top.document.getElementById("overdiv");
   var screenarray=allscreens;
   var left=parseInt(overdiv.scrollLeft);
   var right=left+parseInt(overdiv.offsetWidth);
   var topb=parseInt(overdiv.scrollTop);
   var bottom=topb+parseInt(overdiv.offsetHeight);
   var topcount=0;
   var bottomcount=0;
   var leftcount=0;
   var rightcount=0;
   var maxc=5;
   var bc="#aaaaff";
   for (var x in screenarray)
		  { 
           if((parseInt(screenarray[x]['xpos'])+140)<left && leftcount<maxc)
           {
              leftcount++;
              continue;
           }
           if((parseInt(screenarray[x]['xpos']))>right && rightcount<maxc)
           {
              rightcount++;
              continue;
           }
           if((parseInt(screenarray[x]['ypos'])+45)<topb && topcount<maxc)
           {
              topcount++;
              continue;
           } 
           if((parseInt(screenarray[x]['ypos']))>bottom && bottomcount<maxc)
           {
              bottomcount++;
              continue;
           }
      }
      //topind=bottom-offsetheight
      if(leftcount>0)
      {
         top.document.getElementById("overdiv").style.borderLeft=leftcount+"px dashed "+bc;
      }
      else
      {
         top.document.getElementById("overdiv").style.borderLeft="2px solid black";
      }
            if(topcount>0)
      {
         top.document.getElementById("overdiv").style.borderTop=topcount+"px dashed "+bc;
      }
      else
      {
         top.document.getElementById("overdiv").style.borderTop="2px solid black";
      }
            if(rightcount>0)
      {
         top.document.getElementById("overdiv").style.borderRight=rightcount+"px dashed "+bc;
      }
      else
      {
         top.document.getElementById("overdiv").style.borderRight="2px solid black";
      }
            if(bottomcount>0)
      {
         top.document.getElementById("overdiv").style.borderBottom=bottomcount+"px dashed "+bc;
      }
      else
      {
         top.document.getElementById("overdiv").style.borderBottom="2px solid black";
      }

      //alert(topcount+ " is top and bottom:"+bottomcount+ " and right: "+rightcount+ " and left:"+leftcount);   
}


function inArray(needle, haystack) {
    var length = haystack.length;
    for(var i = 0; i < length; i++) {
        if(haystack[i] == needle) return true;
    }
    return false;
}
