function getMouseXY(e) {
  if (browser=="Microsoft Internet Explorer") { // grab the x-y pos.s if browser is IE
   tempX = e.clientX + document.getElementById("SVGguy").scrollLeft;
    tempY = e.clientY + document.getElementById("SVGguy").scrollTop;
  } else {  // grab the x-y pos.s if it isn't 
    tempX = e.pageX;
    tempY = e.pageY;
  }  
  if (tempX < 0)tempX = 0;
  if (tempY < 0)tempY = 0;  
  return true;
}
