 }
 attach2=0;
 attachLock=false;
 return false;
 }
 else return false;

 //attachLock=true;
 //document.getElementById("attach").setAttribute("fill","red");

 // then the next click on a box means "start here"
 //document.getElementById("SVGguy").removeEventListener("mousedown",dragHandler,false);
 //document.getElementById("SVGguy").addEventListener("click",attachProc,false);
 // then the next click on different box NOT connected to already means "go here""

 } 

 function attachProc(e)
 {
  if(attach1==0)
  {
   attachStart(e);
  }
  else 
  {
   attachFinish(e);
  }
 }                                

 function attachStart(id)
 {
   if(id.substr(0,3)!="box") id="box"+id;
   var idnum=parseInt(id.substr(3));
   if(connx[idnum])
   {
      if(connx[idnum].length>=8)
      {
        return false;
      }

   }

   var target=document.getElementById(id);
   //var target = e.target != null ? e.target : e.srcElement;
   //if(target.getAttribute("id").substring(0,3)=="box")
   if(id)
   {
   closeMenu();
      attachLock=1;
      document.getElementById("attach").setAttribute("fill","purple");
      // get the box even if clicking on x or >> or something
      attach1=id;
      rtarget=document.getElementById(attach1);
      rtarget.setAttribute("style","cursor:not-allowed");
      //rtarget.setAttribute("fill","#ffddff");
      rtarget.setAttribute("stroke","#ee88ee");

       document.getElementById("SVGguy").removeEventListener("mousedown",dragHandler,false);
 document.getElementById("SVGguy").addEventListener("click",attachFinish,false);

      return false;
   }
   else
   { 
   return false;
   }
 }

 function attachFinish(e)
 {

   var target = e.target != null ? e.target : e.srcElement;
   if(target.getAttribute("id").substring(0,3)=="box") // is it a box?
   {
      // get the box even if clicking on x or >> or something
      // is it a box we're not already connected to?
      if(attach2!=0 && attach1!=0)
      {
       olditem=document.getElementById(attach1);
       olditem.setAttributeNS(null,"stroke","rgb(0,0,0)");
      // olditem.setAttributeNS(null,"fill","rgb(204,204,255)");
      }
      attach2=target.getAttribute("id");
      if(attach2.substring(attach2.length-4)=="text") attach2=attach2.substring(0,attach2.length-4);
      // is it the same box? then cancel
      if(attach1==attach2)   // if you're clicking on the same thing twice, cancel
      {
       olditem=document.getElementById(attach1);
       olditem.setAttributeNS(null,"stroke","rgb(0,0,0)");
       //olditem.setAttributeNS(null,"fill","rgb(204,204,255)");
       startAttach();
       return false;
      }
      if(attach1.substring(0,3)=="box")attach1=attach1.substring(3);
      if(attach2.substring(0,3)=="box")attach2=attach2.substring(3);
        if(getx[attach2])
        {
             for(var i=0; i<getx[attach2].length; i++)
             {
              if(getx[attach2][i]==attach1) 
              {
              startAttach();
              return false;
              }
             }
        }
        // if the two aren't already connected to each other, then [prompt and] go for it

      makeConnector(attach1,attach2,false);
      connect(attach1,attach2);
      updateConnectors(attach2);
      updateDB(allscreens);
      startAttach(); 
      return false;
   }
   else
   { 
   return false;
   }
 }

 function detachStart(id)
 {
    if(id.substr(0,3)!="box") id="box"+id;
   var target=document.getElementById(id);
   if(id)
   {
   closeMenu();
      attachLock=1;
      document.getElementById("detach").setAttribute("fill","red");
      // get the box even if clicking on x or >> or something
      attach1=id;
      rtarget=document.getElementById(attach1);
      rtarget.setAttribute("style","cursor:not-allowed");
      //rtarget.setAttribute("fill","#ffddff");
      rtarget.setAttribute("stroke","#eeaaee");

      document.getElementById("SVGguy").removeEventListener("mousedown",dragHandler,false);
      document.getElementById("SVGguy").addEventListener("click",detachFinish,false);

      return false;
   }
   else
   { 
   return false;
   }
 }

 function detachFinish(e)
 {
    var target = e.target != null ? e.target : e.srcElement;
   if(target.getAttribute("id").substring(0,3)=="box") // is it a box?
   {

      // get the box even if clicking on text or something
      // is it a box we're not already connected to?
      if(attach2!=0 && attach1!=0)
      {
       olditem=document.getElementById(attach1);
       olditem.setAttributeNS(null,"stroke","rgb(0,0,0)");
      // olditem.setAttributeNS(null,"fill","rgb(204,204,255)");
      }
      attach2=target.getAttribute("id");  
      if(attach2.substring(attach2.length-4)=="text") attach2=attach2.substring(0,attach2.length-4);
      // is it the same box? then cancel
      if(attach1==attach2)   // if you're clicking on the same thing twice, cancel
      {
       olditem=document.getElementById(attach1);
       olditem.setAttributeNS(null,"stroke","rgb(0,0,0)");
      // olditem.setAttributeNS(null,"fill","rgb(204,204,255)");
       startAttach();
       return false;
      }
      if(attach1.substring(0,3)=="box")attach1=attach1.substring(3);
      if(attach2.substring(0,3)=="box")attach2=attach2.substring(3);

        if(getx[attach2])
        {
             for(var i=0; i<getx[attach2].length; i++)
             {
              if(getx[attach2][i]==attach1) 
              {
                 removeConnector(attach1,attach2);
                 getx[attach2].splice(getx[attach2].indexOf(parseInt(attach1)),1);
                 connx[attach1].splice(connx[attach1].indexOf(parseInt(attach2)),1);

                 if(dconnx[attach1]) if(inArray(attach2,dconnx[attach1])) dconnx[attach1].splice(dconnx[attach1].indexOf(attach2),1);
                 updateDB(allscreens);
                 startAttach();
              return false;
              }
             }
        }
        // if the two aren't already connected to each other, then give up

      startAttach(); 
      return false;
   }
   else
   { 
   return false;
   }
 }



 function divMoveHandler(e)
 {

   if (e == null) { e = window.event }
   var target = e.target != null ? e.target : e.srcElement; 
      //if (perfcount>=perfneed){

      var newx=e.clientX-tempX;
      var newy=e.clientY-tempY;
      divScrollX-=newx;
      divScrollY-=newy;

      var overdiv=top.document.getElementById("overdiv");
      overdiv.scrollLeft=divScrollX;
      overdiv.scrollTop=divScrollY;
      if(overdiv.scrollLeft!=divScrollX) divScrollX=overdiv.scrollLeft;
      if(overdiv.scrollTop!=divScrollY) divScrollY=overdiv.scrollTop;
     // checkOffScreen();
      perfcount=0;

      //else if(target.getAttribute("id")!="SVGguy") cleanup();
     /* else {
           perfcount++;
           return false;
      }*/
 }




 function moveHandler(e){
	 if (e == null) { e = window.event } 
      if (dragOK && perfcount>=perfneed){
      var newx=e.clientX-dragXoffset;
      var newy=e.clientY-dragYoffset;
      var newxt=e.clientX-dragXoffsett;
      var newyt=e.clientY-dragYoffsett;
         if (newx+125>3600)
         {
         newx=3600-125;
         newxt=newx+30;
         }
         if (newx<=0) 
         {
         newx=0;
         newxt=newx+30;
         }
         if (newy+55>1800)
         {
         newy=1800-55;
         newyt=newy+20;
         }     
         if (newy<=0) 
         {
         newy=0;
         newyt=newy+20;
         }
         savedTarget.setAttributeNS(null,"x",newx+'px');
         savedTarget.setAttributeNS(null,"y",newy+'px');

         savedTitle.setAttributeNS(null,"x",newxt+'px');
         savedTitle.setAttributeNS(null,"y",newyt+'px');
         if (!(ieversion && ieversion<9)) updateConnectors(savedTarget.getAttributeNS(null,"id"));
         perfcount=0;
         justmoved=savedTarget.getAttribute("id");
         var jmnum=justmoved.substr(3);
         allscreens[jmnum]['xpos']=newx;
         allscreens[jmnum]['ypos']=newy;
         targetmoved=1;
         return false;
      }
      else if(dragOK) 
      {
       perfcount++;
       return false;
      }
   }

   function cleanup(e) {  // just back to business as usual after dragging
       dragOK=false;
       var overdiv=top.document.getElementById("overdiv");
       checkOffScreen();
    document.getElementById("SVGguy").removeEventListener("mousemove",moveHandler,false);
    document.getElementById("SVGguy").removeEventListener("mousemove",divMoveHandler,false);
     //document.getElementById("SVGguy").addEventListener("mousemove",getMouseXY,false);
     if(savedTarget)
     {
        savedTarget.style.cursor="move";
     }   
      if(savedTarget && !menuopen && targetmoved) 
      {
        updateDB(allscreens);
      }

      document.getElementById("SVGguy").removeEventListener("mouseup",cleanup,false);
      if (browser=="Microsoft Internet Explorer" && savedTarget) updateConnectors(savedTarget.getAttributeNS(null,"id"));
      savedTarget=null;
      return true;
   }

