      if(!id) return false;
      id=String(id);
      target=document.getElementById("box"+id);
      var targett="box"+id+"text";
      var targettext=document.getElementById(targett);
	    savedTarget=target; 
	    savedTitle=targettext;

         target.style.cursor=htype;
         dragOK=true;
         dragXoffset=e.clientX-parseInt(savedTarget.getAttributeNS(null,"x"));
         dragYoffset=e.clientY-parseInt(savedTarget.getAttributeNS(null,"y"));

         dragXoffsett=e.clientX-parseInt(savedTitle.getAttributeNS(null,"x"));
         dragYoffsett=e.clientY-parseInt(savedTitle.getAttributeNS(null,"y"));

         document.getElementById("SVGguy").addEventListener("mousemove",moveHandler,false);
         document.getElementById("SVGguy").addEventListener("mouseup",cleanup,false);
         e.preventDefault();
         return false;
      }
      else if (target.getAttribute("id")=="SVGguy") 
      {
       //alert(e.clientX+" and "+e.clientY);
