      function removeBox(boxid)
      {    

        if(attachLock) return false;
        var box=document.getElementById("box"+boxid);
        var group=document.getElementById("box"+boxid+"group");
        closeMenu();
        // need to remove from field, from arrays, remove any connectors.
        //1: from field (take all members of the node's group out)
        for(var i=(group.childNodes.length-1);i>=0;i--)
        {
          group.removeChild(group.childNodes[i]);
        }

        //2: connectors and arrays. for each entry in the connector arrays, remove the connector, remove the entry in the partner array for the deleted 
        if(connx[boxid])
         {                                      
              for(var i=0;i<connx[boxid].length; i++)
              {              
              removeConnector(boxid,connx[boxid][i]);
              getx[connx[boxid][i]].splice(getx[connx[boxid][i]].indexOf(boxid),1);
              }
              connx[boxid]=new Array();
              dconnx[boxid]=new Array();
         }
         if(getx[boxid])
         {
              for(var i=0;i<getx[boxid].length; i++)
              {                   
              removeConnector(getx[boxid][i],boxid);
              connx[getx[boxid][i]].splice(connx[getx[boxid][i]].indexOf(boxid),1);
              if(dconnx[getx[boxid][i]])dconnx[getx[boxid][i]].splice(dconnx[getx[boxid][i]].indexOf(boxid),1);
              }
              getx[boxid]=new Array();    
         }
         allscreens[boxid]["deleted"]=1;

      }

      function removeConnector(id1,id2)
      {
      var conn=document.getElementById(id1+"to"+id2);
      conn.parentNode.removeChild(conn);
      var si=allscreens[id1];
      var ttext= new Array();
        for (var i=1; i<=8; i++)
        {
            if(si["choice"+i]=="") continue;
            ttext[1]="";
            ttext=si["choice"+i].split("|Q-D-|");
              if(ttext[1]==allscreens[id2]["id"])
              {
                allscreens[id1]["choice"+i]="";
              }


        }
      }

      function connect(id1,id2)
      {
            if(!connx[id1]) 
      {
         connx[id1]=new Array();
         connx[id1][0]=id2;
      }
      else if(inArray(id2,connx[id1]))
           {
            return false;
           }
      else connx[id1][connx[id1].length]=id2;


      if(!getx[id2]) 
      {
         getx[id2]=new Array();
         getx[id2][0]=id1;
      }
      else getx[id2][getx[id2].length]=id1; 


    // now we save the information... make sure we're not adding another one for pre-made stuff
      var firstfree=0;
      for(var num=1; num<=8;num++)
      {
         if((!allscreens[id1]["choice"+num] || allscreens[id1]["choice"+num]=="") && firstfree==0)
         {
            firstfree=num;
         }
         else
         {
           var we=allscreens[id1]["choice"+num].split("|Q-D-|");
           if(we[1]==allscreens[id2]["id"]) return true;
         }

      }
      allscreens[id1]["choice"+firstfree]=allscreens[id2]["name"]+"|Q-D-|"+allscreens[id2]["id"];

            return true;

      }

      function updateConnectors(boxid)
      {
        if(boxid.substr(0,3)=="box") boxid=boxid.substr(3);
         if(connx[boxid])
         {
              for(var i=0;i<connx[boxid].length; i++)
              {
              var apath=document.getElementById(boxid+"to"+connx[boxid][i]);        
              lineOrPath(boxid,connx[boxid][i],apath);     
              }
         }
         if(getx[boxid])
         {
              for(var i=0;i<getx[boxid].length; i++)
              {
              var apath=document.getElementById(getx[boxid][i]+"to"+boxid);
              lineOrPath(getx[boxid][i],boxid,apath);     
              }
         }
      }

      function replace(which,sort,atts)
      {
        if(sort=="line")
        { // it is currently a path, needs to be a line.
           var newPath = document.createElementNS(svgNS,"line");

             newPath.setAttributeNS(null,"x1",atts[0]);
             newPath.setAttributeNS(null,"y1",atts[1]);
             newPath.setAttributeNS(null,"x2",atts[2]);
             newPath.setAttributeNS(null,"y2",atts[3]);
             newPath.setAttributeNS(null,"stroke",which.getAttribute("stroke"));
             newPath.setAttributeNS(null,"stroke-width","3");
             newPath.setAttributeNS(null,"fill","none");
             newPath.setAttributeNS(null,"id",atts[4]);
             newPath.setAttributeNS(null,"class","itsaline");
             which.parentNode.replaceChild(newPath,which);

        }
          if(sort=="path")
        { // it is currently a line, needs to be a path.
           var newPath = document.createElementNS(svgNS,"path");

             newPath.setAttributeNS(null,"d",atts[0]);
             newPath.setAttributeNS(null,"stroke",which.getAttribute("stroke"));
             newPath.setAttributeNS(null,"fill","none");
             newPath.setAttributeNS(null,"stroke-width","3");
             newPath.setAttributeNS(null,"id",atts[1]);
             newPath.setAttributeNS(null,"class","itsapath");
             which.parentNode.replaceChild(newPath,which);

        }
      }

      function lineOrPath(id1,id2,which)
      {
        var box1=document.getElementById("box"+id1);
        var box2=document.getElementById("box"+id2);
        var b1x=parseInt(box1.getAttributeNS(null,"x"));
        var b2x=parseInt(box2.getAttributeNS(null,"x"));
        var b1w=parseInt(box1.getAttributeNS(null,"width"));
        if(b1x+b1w>=b2x+3) 
        {
        var newd=figurePath(box1,box2);
        if (which.getAttributeNS(null,"class")=="itsapath")
        {
        which.setAttributeNS(null,"d",newd);
        }
        else
        {
        var attribs=new Array();
        attribs[0]=newd
        attribs[1]=id1+"to"+id2;
        replace(which,"path",attribs);
        }
        }
        else
        {
        var linear=figureLine(box1,box2);
        if (which.getAttribute("class")=="itsaline")
        {
        which.setAttribute("x1",linear[0]);
        which.setAttribute("y1",linear[1]);
        which.setAttribute("x2",linear[2]);
        which.setAttribute("y2",linear[3]);
         }
         else
         {
           linear[4]=id1+"to"+id2;
           replace(which,"line",linear);
         }

        }
      }

      function figureLine(box1,box2)
      {
        //var box1=document.getElementById(id1);
        //var box2=document.getElementById(id2);
        var b1x=parseInt(box1.getAttributeNS(null,"x"));
        var b1y=parseInt(box1.getAttributeNS(null,"y"));
        var b1h=parseInt(box1.getAttributeNS(null,"height"));
        var b1w=parseInt(box1.getAttributeNS(null,"width"));

        var b2x=parseInt(box2.getAttributeNS(null,"x"));
        var b2y=parseInt(box2.getAttributeNS(null,"y"));
        var b2h=parseInt(box2.getAttributeNS(null,"height"));
        var b2w=parseInt(box2.getAttributeNS(null,"width"));

        var r=new Array();
        r[0]=b1x+b1w; // x1
        r[1]=b1y+(b1h*.5); //y1
        r[2]=b2x;          // x2
        r[3]=b2y+(b1h*.5); // y2
        return r;
      }

      function figurePath(box1,box2)
      {
        //var box1=document.getElementById(id1);
        //var box2=document.getElementById(id2);

        var b1x=parseInt(box1.getAttributeNS(null,"x"));
        var b1y=parseInt(box1.getAttributeNS(null,"y"));
        var b1h=parseInt(box1.getAttributeNS(null,"height"));
        var b1w=parseInt(box1.getAttributeNS(null,"width"));

        var b2x=parseInt(box2.getAttributeNS(null,"x"));
        var b2y=parseInt(box2.getAttributeNS(null,"y"));
        var b2h=parseInt(box2.getAttributeNS(null,"height"));
        var b2w=parseInt(box2.getAttributeNS(null,"width"));
        var newxs=b1x+b1w;
        var newys=b1y+(b1h*.5);
        var newxe=b2x;
        var newye=b2y+(b1h*.5);
        // control points

        var diff=(b1x+b1w)-(b2x+3);
        var hdiff=diff*.5;
        if(hdiff>50) hdiff=50;
        var newxc1=b1x+b1w+(hdiff);
        var newxc2=b2x-(hdiff);
         if(b1y<b2y)
         {
          var newyc1=b1y+b1h+(hdiff);
          var newyc2=b2y-(hdiff);
         }
         else
         {
          var newyc1=b1y-(hdiff);
          var newyc2=b2y+b2h+(hdiff);
         }
        var newd="M"+newxs+","+newys+" C"+newxc1+","+newyc1+" "+newxc2+","+newyc2+" "+newxe+","+newye;
        return newd;
      }

      function makeConnector(id1,id2,isline)
      {
        if(connx[id1])
        {
           if(inArray(id2,connx[id1]))
           {
            return false;
           }
           }
            if(isline==true) {
            var xy=figureLine(document.getElementById("box"+id1),document.getElementById("box"+id2));
            var newPath = document.createElementNS(svgNS,"line");

             newPath.setAttributeNS(null,"x1",xy[0]);
             newPath.setAttributeNS(null,"y1",xy[1]);
             newPath.setAttributeNS(null,"x2",xy[2]);
             newPath.setAttributeNS(null,"y2",xy[3]);
             newPath.setAttributeNS(null,"stroke-width","3");
             newPath.setAttributeNS(null,"stroke","rgb(0,0,0)");
             newPath.setAttributeNS(null,"fill","none");
             newPath.setAttributeNS(null,"id",id1+"to"+id2);
             newPath.setAttributeNS(null,"class","itsaline");
             }
             else 
             {
            var newd=figurePath(document.getElementById("box"+id1),document.getElementById("box"+id2));
            var newPath = document.createElementNS(svgNS,"path");

             newPath.setAttributeNS(null,"stroke","rgb(0,0,0)");
             newPath.setAttributeNS(null,"stroke-width","3");
             newPath.setAttributeNS(null,"fill","none");
             newPath.setAttributeNS(null,"id",id1+"to"+id2);
             newPath.setAttributeNS(null,"class","itsapath");
             newPath.setAttributeNS(null,"d",newd);
             }

             document.getElementById("firstGroup").appendChild(newPath);

      }

