             }
                          var newindex = highlightedfriends.length;
                          highlightedfriends[newindex] = new Array();
                          highlightedfriends[newindex]["item"]=item;
                          highlightedfriends[newindex]["path"]=path;
             }

        }

      }

      function dimFriends(e)
      {
          var target = e.target != null ? e.target : e.srcElement;
          if(!target.getAttribute("id")) return false;
          var id=target.getAttribute("id").substr(3);

        for (var j=1; j<9; j++)
        {
             var label=document.getElementById("pathlabel"+(j));
             if(document.getElementById("pathtext"+j))var ltext=document.getElementById("pathtext"+(j));

            if(ltext.firstChild)
            {
             ltext.removeChild(ltext.firstChild);
             ltext.setAttribute("x",-110);
             ltext.setAttribute("y",-110);
