      function getEditScreen()
      {
         var screen=top.screentoedit;
         if(!screen || screen==0) return false;
         top.screentoedit=0;
         mid=screen;
         top.switchSec("vised");
         editScreen(screen, 0, 1);
      }

      function openMenu(e)
      {
      if(top.advavail=="public") return false;
      if(e.detail>1) return false;
      if(attachLock) return false;
        var target = e.target != null ? e.target : e.srcElement;
       if(menuopen==1) // close it up
       {
        if(mid==parseInt(target.getAttribute("id").substr(3)))
        {
        closeMenu();
        return false;
        }
        else 
        {
        closeMenu();
        }
       }
        //getMouseXY(e);


        mid=parseInt(target.getAttribute("id").substr(3));
        mid=String(mid);
        if(target=document.getElementById('box'+mid))
        {
        }
        else return false;
        var theight=target.getAttribute("height");
        var tx=target.getAttribute("x");
        var ty=target.getAttribute("y");
        tox=tx;
        toy=parseInt(ty)+parseInt(theight)-3;
        if(justmoved && justmoved.substr(3)==mid)   // we just dragged this box so no menu... but clear the justmoved
        {
          justmoved=0;
          mid=0;
          return false;
        }
        var boxmenu=document.getElementById("menuGroup");
        var cthing=null;

        for(var i=0; boxmenu.childNodes.length>i; i++)
        {
            if(boxmenu.childNodes[i].id)
            {
            cthing=document.getElementById(boxmenu.childNodes[i].id) ;
            cthing.setAttribute("x",parseInt(cthing.getAttribute("x"))+510+parseInt(tox));
            cthing.setAttribute("y",parseInt(cthing.getAttribute("y"))+510+parseInt(toy));
            }
        }
        menuopen=1;
        //!!!menutimer!!!    
      }

      function closeMenu()
      {
        if(!menuopen)
        {
        mid=0;
        return false;
        }   
        var midbox=document.getElementById("box"+mid);
        var theight=midbox.getAttribute("height");
        var tx=midbox.getAttribute("x");
        var ty=midbox.getAttribute("y");
        var boxmenu=document.getElementById("menuGroup");
        var cthing=null;
        for(var i=0; boxmenu.childNodes.length>i; i++)
        {
            if(boxmenu.childNodes[i].id)
            {
            cthing=document.getElementById(boxmenu.childNodes[i].id);
            cthing.setAttribute("x",parseInt(cthing.getAttribute("x"))-510-parseInt(tox));
            cthing.setAttribute("y",parseInt(cthing.getAttribute("y"))-510-parseInt(toy));
            }
        }
      menuopen=0;
      mid=0;
      return false;
      }

      function editScreen(sid, udb, quick)
      {
        if(top.advavail=="public") return false;
        if(!udb)  udb=0;
        if(!quick)  quick=0;
        if(!sid || sid==0) 
          {
          getEditScreen();
          return false;
          }
          if(sid.target) 
          {
            var tar = sid.target != null ? sid.target : sid.srcElement;
            sid=tar.getAttribute("id");
            sid=String(parseInt(sid.substring(3)));

          }
        var du=top.document.getElementById("divup1");
        if(du.innerHTML==false || du.style.display=="none" || true) 
        {

           top.screentoedit=sid;
           var size=top.openDivUp('editscreen.php', new Array('id','screen'), new Array(top.advid,sid), false, sid, quick);

        }

      }

      function saveAndClose()
      {
         updateDB(allscreens);
         if(top.document.getElementById("divup1").style.display="block")
         {
            closeDivUp();
         }
      }
